import random
import time

class NajikaBrain:
    def __init__(self):
        self.energy = 100
        self.mood = "excited"
        self.bonds = 0
        self.level = 1
        self.experience = 0
        self.last_interaction = time.time()

        # Erweiterte Persönlichkeit aus Dokument A
        self.personality = {
            'catchphrases': ['Kuja!', 'Kuja kuja!', 'Das ist großartig!'],
            'favorite_topics': ['explosion', 'magie', 'abenteuer', 'freundschaft'],
            'battle_ready': True,
            'explosion_mastery': 95
        }

        self.responses = {
            'explosion': [
                "💥 EXPLOSION! Mein ultimativer Zauber! Die pure Kraft der Zerstörung! Kuja!",
                "⚡ Explosion-Magie ist Perfektion in Reinform! Kuja kuja!",
                "🔥 Niemand beherrscht Explosion besser als ich! Kuja!"
            ],
            'training': [
                "🎯 Training macht den Meister! Lass uns üben! Kuja!",
                "💪 Jede Übung bringt uns der Perfektion näher! Kuja!",
                "⚔️ Kampftraining aktiviert! Bereit für alles! Kuja!"
            ],
            'freundschaft': [
                "💖 Wahre Freundschaft ist die stärkste Magie! Kuja!",
                "✨ Zusammen sind wir unschlagbar! Kuja kuja!",
                "🤝 Unsere Verbindung wird immer stärker! Kuja!"
            ],
            'default': [
                "✨ Najika lauscht gespannt... Erzähl mehr! Kuja!",
                "🎭 Interessant! Das bringt meine Gedanken zum Leuchten! Kuja!",
                "💫 Najika versteht und lernt dazu! Kuja kuja!"
            ]
        }

    def respond(self, message):
        self.last_interaction = time.time()
        self.experience += 1

        # Level-Up System
        if self.experience % 10 == 0:
            self.level += 1
            self.bonds += 1

        msg_lower = message.lower()

        # Intelligente Antwort-Auswahl
        for topic, responses in self.responses.items():
            if topic != 'default' and topic in msg_lower:
                response = random.choice(responses)
                self.energy = min(100, self.energy + 2)  # Energie steigt bei Interaktion
                return response

        # Default-Antwort
        return random.choice(self.responses['default'])

    def get_status(self):
        return {
            'energy': self.energy,
            'mood': self.mood,
            'bonds': self.bonds,
            'level': self.level,
            'experience': self.experience,
            'explosion_mastery': self.personality['explosion_mastery']
        }

