from flask import Flask, render_template
from flask_socketio import SocketIO, emit
from najika_brain import NajikaBrain
import os

app = Flask(__name__)
app.config['SECRET_KEY'] = 'najika_explosion_key'
socketio = SocketIO(app, cors_allowed_origins="*")

# Najika-Brain initialisieren
najika = NajikaBrain()

@app.route('/')
def home():
    return render_template('najika_visual.html')

@socketio.on('chat')
def handle_chat(data):
    user_message = data['message']

    # Najika antwortet mit ihrer vollen Persönlichkeit
    response = najika.respond(user_message)
    current_status = najika.get_status()

    # Antwort an Browser senden
    emit('najika_response', {
        'message': response,
        'status': current_status,
        'timestamp': 'jetzt'
    })

@socketio.on('get_najika_status')
def handle_status_request():
    current_status = najika.get_status()
    emit('status_update', current_status)

@socketio.on('connect')
def handle_connect():
    print("✅ Benutzer verbunden!")
    welcome_msg = "💫 Najika: Kuja! Verbindung hergestellt! Bereit für Abenteuer!"
    emit('najika_response', {
        'message': welcome_msg,
        'status': najika.get_status()
    })

@socketio.on('disconnect')
def handle_disconnect():
    print("❌ Benutzer getrennt!")

if __name__ == '__main__':
    # Templates-Ordner prüfen
    if not os.path.exists('templates'):
        os.makedirs('templates')

    print("🚀 NAJIKA FINAL VERSION startet...")
    print("🧠 Erweiterte KI-Persönlichkeit geladen!")
    print("📍 Öffne: http://localhost:5000")
    print("💥 Najika ist bereit für ALLES!")

    socketio.run(app, host='localhost', port=5000, debug=True)

